components.css:
.ds-service-list{display:grid;grid-template-columns:1fr;font-family:Vazirmatn,sans-serif;color:var(--text,#f5f4fa)}.ds-service-list>.ds-service-card{direction:rtl}.ds-service-list .ds-app-icon{display:grid;place-items:center;font-family:Arial,sans-serif;font-weight:600;border:1px solid currentColor;color:#b28aff;background:#10052e}.ds-service-body>a{text-decoration:none}.ds-service-body>a svg{fill:none;stroke:currentColor;stroke-width:1.65}.ds-service-body>a:focus-visible{outline:2px solid #c99cff;outline-offset:6px}
.ds-services.ds-panel-section{max-width:1480px;margin:0 auto 60px;padding:20px 40px 35px}
.ds-services .ds-section-heading{margin-bottom:34px}
.ds-services .ds-section-heading h2{font-size:32px;font-weight:600}
.ds-service-list{gap:26px;grid-template-columns:repeat(3,minmax(0,1fr))}
.ds-service-list>.ds-service-card,.ds-service-list>.ds-service-card+div{--card-accent:#bd8de9;position:relative;min-height:0;padding:0;border:1px solid #45324f;border-radius:16px;background:#15111e;overflow:hidden}
.ds-service-list>.ds-motion-service{--card-accent:#c998fb;background:#181124;border-color:#674580}
.ds-service-list>.ds-design-service{--card-accent:#79c9e5;background:#111a22;border-color:#2e4554}
.ds-service-list>.ds-service-card:after{display:none}
.ds-service-visual{height:270px;position:relative;background:radial-gradient(ellipse at 50% 85%,#693a8a30,transparent 70%),#100c18;overflow:hidden;border-bottom:1px solid #3a2a48}
.ds-design-service .ds-service-visual{background:radial-gradient(ellipse at 50% 85%,#366b8630,transparent 70%),#0b151d;border-color:#263d4b}
.ds-service-windowbar{display:flex;align-items:center;direction:ltr;gap:12px;padding:16px 19px;font-size:12px;letter-spacing:.3px;color:#bbadc9}
.ds-service-windowbar .ds-app-icon{float:none;width:31px;height:31px;border-radius:6px;font-size:19px;margin:0}
.ds-service-windowbar>i{width:5px;height:5px;margin-left:auto;border-radius:50%;background:var(--card-accent)}
.ds-service-body{padding:27px 28px 28px}
.ds-service-body h3{font-size:27px;font-weight:600;margin:0 0 13px}
.ds-service-body p{font-size:16px;line-height:1.95;max-width:35ch;min-height:62px;margin:0;color:#b8adc4}
.ds-service-body>a{display:flex;align-items:center;justify-content:space-between;gap:8px;color:var(--card-accent);font-size:13px;margin-top:25px;padding-top:18px;border-top:1px solid #64537345}
.ds-service-body>a svg{width:19px;height:19px;transition:transform .25s}
.ds-service-body>a:hover svg{transform:translateX(-5px)}
.ds-editing-preview{position:absolute;inset:65px 28px 16px;direction:ltr}
.ds-preview-screen{height:111px;width:72%;margin:auto;display:grid;place-items:center;position:relative;background:linear-gradient(135deg,#322042,#20172d);border:1px solid #806097;border-radius:7px;transform:rotate(-5deg);box-shadow:8px 12px 18px #0004;transition:transform .35s}
.ds-preview-screen:before,.ds-preview-screen:after{content:'';position:absolute;width:70%;height:52%;border:1px solid #9c77b344;border-radius:3px;transform:rotate(13deg)}
.ds-preview-screen:after{width:43%;height:72%;transform:rotate(-17deg)}
.ds-preview-screen svg{width:39px;height:39px;fill:#c4a0e6;stroke:none;z-index:1}
.ds-screen-corner{position:absolute;left:9px;right:9px;bottom:9px;height:2px;background:#be8ce333}
.ds-preview-timeline{position:absolute;bottom:0;left:0;right:0;height:56px;border-top:1px solid #594467;display:flex;flex-direction:column;gap:4px;padding:8px 8px 0}
.ds-preview-timeline i{height:10px;border-radius:2px;background:#8155ad;width:73%}.ds-preview-timeline i:nth-child(2){width:65%;margin-left:22%;background:#554880}.ds-preview-timeline i:nth-child(3){width:84%;background:#526eac}
.ds-preview-timeline>span{position:absolute;height:59px;width:1px;background:#cfa4f0;top:-3px;left:38%}.ds-preview-timeline>span:before{content:'';position:absolute;top:0;left:-4px;width:9px;height:9px;background:#cfa4f0;clip-path:polygon(0 0,100% 0,100% 50%,50% 100%,0 50%)}
.ds-motion-preview{position:absolute;inset:67px 20px 5px;direction:ltr}
.ds-motion-preview svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible;stroke:none}.ds-motion-path{fill:none;stroke:#c78ef3;stroke-width:1.5;stroke-dasharray:4 5}.ds-motion-preview circle{fill:#d3a8f4}
.ds-motion-tile{position:absolute;width:96px;height:96px;border-radius:24px;left:calc(50% - 48px);top:30px;border:1px solid #c592ed;background:linear-gradient(140deg,#8854b5,#3b1e60 60%,#a36cdd);transform:rotate(-17deg);box-shadow:8px 10px 0 -3px #392252,13px 18px 24px #0005;transition:transform .35s}
.ds-motion-tile:before{content:'';position:absolute;inset:20px;border:1px solid #ead3ff99;border-radius:50%}.ds-motion-tile:after{content:'';position:absolute;inset:33px;border:1px solid #ead3ff99;transform:rotate(45deg)}
.ds-motion-node{position:absolute;left:23%;top:61%;width:10px;height:10px;background:#d9b0ff;border:1px solid #eddaff;transform:rotate(45deg)}
.ds-design-preview{position:absolute;inset:70px 25px 15px;direction:ltr}
.ds-design-sheet{position:absolute;width:137px;height:132px;left:calc(50% - 68px);top:7px;border:1px solid #61879a;border-radius:7px}
.ds-sheet-back{background:#234153;transform:rotate(-15deg) translate(-13px,2px)}
.ds-sheet-front{background:linear-gradient(140deg,#385c70,#142936);transform:rotate(9deg);display:grid;place-items:center;color:#ade4ed;transition:transform .35s;box-shadow:8px 13px 22px #0004}
.ds-sheet-front>span{font-family:Georgia,serif;font-size:65px;line-height:1}.ds-sheet-front>i{position:absolute;width:5px;height:5px;background:#87b8ca;top:8px;left:8px}.ds-sheet-front>i:nth-of-type(2){left:auto;right:8px}.ds-sheet-front>i:nth-of-type(3){top:auto;bottom:8px}
.ds-design-swatches{position:absolute;bottom:0;left:calc(50% - 72px);display:flex;gap:9px;padding:7px 10px;border:1px solid #547181;border-radius:6px;background:#172731;transform:rotate(-4deg)}
.ds-design-swatches i{width:21px;height:21px;border-radius:3px;background:#d8baf2}.ds-design-swatches i:nth-child(2){background:#966ed1}.ds-design-swatches i:nth-child(3){background:#5e9cbb}.ds-design-swatches i:nth-child(4){background:#d3ebee}
@media(hover:hover) and (prefers-reduced-motion:no-preference){.ds-editing-service:hover .ds-preview-screen{transform:rotate(0deg) translateY(-3px)}.ds-motion-service:hover .ds-motion-tile{transform:rotate(-7deg) translateY(-4px)}.ds-design-service:hover .ds-sheet-front{transform:rotate(2deg) translateY(-3px)}}

@media(prefers-reduced-motion:reduce){.ds-service-body>a svg,.ds-motion-tile{transition:none!important}}
